import{_ as o,c as d,o as t,b2 as r}from"./chunks/framework.CUhoHPxN.js";const h=JSON.parse('{"title":"用户管理设计文档","description":"","frontmatter":{},"headers":[],"relativePath":"superpowers/specs/2026-05-14-user-management-design.md","filePath":"superpowers/specs/2026-05-14-user-management-design.md"}'),s={name:"superpowers/specs/2026-05-14-user-management-design.md"};function c(a,e,l,i,n,u){return t(),d("div",null,[...e[0]||(e[0]=[r('<h1 id="用户管理设计文档" tabindex="-1">用户管理设计文档 <a class="header-anchor vp-link" href="#用户管理设计文档" aria-label="Permalink to &quot;用户管理设计文档&quot;">​</a></h1><h2 id="_1-背景与目标" tabindex="-1">1. 背景与目标 <a class="header-anchor vp-link" href="#_1-背景与目标" aria-label="Permalink to &quot;1. 背景与目标&quot;">​</a></h2><p>在系统管理域内实现「用户」全生命周期管理：多条件分页查询、列表展示（含部门与角色聚合展示）、多选/单选控制批量操作、状态开关（切换前二次确认）、新增/编辑（弹窗）、单条与批量删除、重置密码、<strong>独立子路由「分配角色」</strong>（勾选角色后保存）、Excel 导入（支持按用户名更新已存在用户）、按当前筛选导出、导入模板下载；错误提示中文、文案清晰。</p><p>原始需求见 <code>原始需求/系统管理/用户管理-需求文档.md</code>。本文档为经 <code>/brainstorming</code> 澄清并确认后的<strong>定稿设计</strong>；与原始需求不一致处（尤其 HTTP 方法、路径字面、岗位能力）以本文为准。</p><h2 id="_2-需求澄清结论-已确认" tabindex="-1">2. 需求澄清结论（已确认） <a class="header-anchor vp-link" href="#_2-需求澄清结论-已确认" aria-label="Permalink to &quot;2. 需求澄清结论（已确认）&quot;">​</a></h2><div class="vp-table"><table><thead><tr><th>序号</th><th>结论</th></tr></thead><tbody><tr><td>1</td><td>写操作统一使用 <strong><code>POST</code></strong>；读操作使用 <strong><code>GET</code></strong>（与 <code>AGENTS.md</code>、《2026-05-14-role-management-design》一致，不对齐原始需求 §7 的 <code>PUT</code>/<code>DELETE</code>）。路径前缀 <strong><code>/system/user</code></strong>，子路径命名风格与 <code>SysRoleController</code> 的 <code>create</code> / <code>update</code> / <code>remove</code> 等一致。</td></tr><tr><td>2</td><td><strong>本迭代不做岗位</strong>：表单、数据模型、导入导出模板均<strong>不包含</strong>岗位字段。</td></tr><tr><td>3</td><td><strong>分配角色</strong>为<strong>独立子路由页面</strong>（非抽屉内完成）；从用户列表进入，保存后返回列表。</td></tr><tr><td>4</td><td>导入时「更新已存在用户」按 <strong><code>user_name</code></strong> 与库表唯一约束 <code>uk_sys_user_name</code> 一致匹配。</td></tr><tr><td>5</td><td><strong>内置超级管理员用户</strong>（种子 <strong><code>user_id = 1</code></strong>，当前迁移中为 <code>admin</code>）：<strong>禁止删除</strong>；<strong>禁止修改 <code>user_name</code></strong>；<strong>禁止将 <code>status</code> 置为停用</strong>；其余字段（昵称、部门、手机、邮箱、性别、备注、<strong>角色</strong>等）允许按权限编辑。</td></tr><tr><td>6</td><td>范围仅限<strong>系统管理—用户管理</strong>前后端、菜单权限种子与验收标准；<strong>不包含</strong>个人中心 profile 大改造；<strong>不包含</strong>列表行级数据权限 SQL 切面（若项目已有切面可后续衔接）。</td></tr><tr><td>7</td><td><strong>新增与编辑用户</strong>：须<strong>至少选择一个角色</strong>（<code>roleIds</code> 非空）；校验失败返回明确业务异常文案。</td></tr></tbody></table></div><h2 id="_3-范围与非范围" tabindex="-1">3. 范围与非范围 <a class="header-anchor vp-link" href="#_3-范围与非范围" aria-label="Permalink to &quot;3. 范围与非范围&quot;">​</a></h2><h3 id="_3-1-实施范围" tabindex="-1">3.1 实施范围 <a class="header-anchor vp-link" href="#_3-1-实施范围" aria-label="Permalink to &quot;3.1 实施范围&quot;">​</a></h3><ul><li>后端：<code>io.github.genkidoudou.web.system.user</code> 包下 Controller / Service / Mapper（<code>SysUserMapper</code> 已存在可复用）/ 已有 <code>SysUser</code> 实体；补充 Bo、QueryBo、Vo、导入导出 Excel 行对象等 DTO。</li><li>与 <strong><code>sys_user</code></strong>、<strong><code>sys_user_role</code></strong>、<strong><code>sys_role</code></strong>（只读校验）、<strong><code>sys_dept</code></strong>（部门名称与树筛选）衔接。</li><li>权限标识与原始需求 §6 一致：<code>system:user:list</code>、<code>add</code>、<code>edit</code>、<code>remove</code>、<code>export</code>、<code>import</code>、<code>resetPwd</code>；分配角色与修改共用 <strong><code>system:user:edit</code></strong>（与原始需求一致）；鉴权与前端 <code>v-hasPermi</code> 对齐。</li><li>Flyway：补充<strong>用户管理</strong>菜单及按钮（<code>perms</code> 如上），并为 <strong><code>role_id = 1</code></strong> 绑定新菜单 id（与 <code>V6</code> 角色菜单迁移方式一致）；菜单 id 取值在实现阶段分配，避免与现有 <code>sys_menu</code> 主键冲突。</li><li>前端：<code>quick-ui</code> 列表页、新增/编辑弹窗、分配角色子页、统一 <code>api/system/user.js</code> 指向 <strong><code>/system/user/*</code></strong>；视觉与交互遵循仓库根目录 <strong><code>DESIGN.md</code></strong>。</li></ul><h3 id="_3-2-明确不做" tabindex="-1">3.2 明确不做 <a class="header-anchor vp-link" href="#_3-2-明确不做" aria-label="Permalink to &quot;3.2 明确不做&quot;">​</a></h3><ul><li>岗位、用户-岗位关联表与相关 UI。</li><li>与原始需求 §7 <strong>路径与方法字面完全一致</strong>的对外契约。</li><li>个人中心（头像、自主改密等）在本变更中一并重构（已有接口可继续独立演进，不在本文验收范围内）。</li></ul><h2 id="_4-数据模型与查询约定" tabindex="-1">4. 数据模型与查询约定 <a class="header-anchor vp-link" href="#_4-数据模型与查询约定" aria-label="Permalink to &quot;4. 数据模型与查询约定&quot;">​</a></h2><h3 id="_4-1-表-sys-user" tabindex="-1">4.1 表 <code>sys_user</code> <a class="header-anchor vp-link" href="#_4-1-表-sys-user" aria-label="Permalink to &quot;4.1 表 `sys_user`&quot;">​</a></h3><p>沿用现有 Flyway 与实体字段（含 <code>user_id</code>、<code>dept_id</code>、<code>user_name</code>、<code>nick_name</code>、<code>email</code>、<code>phonenumber</code>、<code>sex</code>、<code>password</code>、<code>status</code>、<code>del_flag</code>、备注与审计字段等）。<strong>不新增</strong>岗位列。</p><h3 id="_4-2-表-sys-user-role" tabindex="-1">4.2 表 <code>sys_user_role</code> <a class="header-anchor vp-link" href="#_4-2-表-sys-user-role" aria-label="Permalink to &quot;4.2 表 `sys_user_role`&quot;">​</a></h3><p>用户与角色多对多；以下写路径须在实现中<strong>逻辑收敛</strong>，避免与角色域「按角色批量授权用户」长期分叉：</p><ul><li><strong>用户侧</strong>：<code>POST /system/user/authRole</code> 全量替换该 <code>user_id</code> 下的角色关联（事务：先删后插或等价策略）。</li><li><strong>角色侧</strong>：已有 <code>POST /system/role/authUser/*</code> 系列仍维护同一表；实现时推荐抽取<strong>单一写入辅助方法</strong>（同模块内私有或极薄共享层），两处仅作为入口，不复制两套不一致的规则。</li></ul><h3 id="_4-3-列表与部门筛选" tabindex="-1">4.3 列表与部门筛选 <a class="header-anchor vp-link" href="#_4-3-列表与部门筛选" aria-label="Permalink to &quot;4.3 列表与部门筛选&quot;">​</a></h3><ul><li>列表需展示<strong>部门名称</strong>：关联 <code>sys_dept</code>（按 <code>dept_id</code>）解析；<code>dept_id</code> 可为空时部门列展示约定为空或「未分配」，实现时写死一种并在本文保持一致。</li><li><strong>部门树筛选</strong>：选中节点 <code>deptId</code> 时，筛选 <strong><code>sys_user.dept_id</code> 落在该节点及其全部子孙部门</strong>范围内的用户。当前 <code>sys_dept</code> 无 <code>ancestors</code> 字段，<strong>在服务端基于全量部门列表计算子孙 <code>dept_id</code> 集合</strong>再拼 <code>IN</code> 条件（与 <code>DeptServiceImpl</code> 树构建思路一致，避免 N+1）。</li></ul><h3 id="_4-4-角色展示" tabindex="-1">4.4 角色展示 <a class="header-anchor vp-link" href="#_4-4-角色展示" aria-label="Permalink to &quot;4.4 角色展示&quot;">​</a></h3><p>列表「角色」列：通过 <code>sys_user_role</code> 关联 <code>sys_role</code> 聚合为 <code>roleNames</code>（或等价字段）；实现可选单次 join 或二次查询，以可读性与性能权衡为准。</p><h2 id="_5-接口契约" tabindex="-1">5. 接口契约 <a class="header-anchor vp-link" href="#_5-接口契约" aria-label="Permalink to &quot;5. 接口契约&quot;">​</a></h2><p>统一响应 <code>R</code>；分页列表使用 <code>PageInfo&lt;T&gt;</code>；Query 含 <code>pageNum</code>、<code>pageSize</code> 及筛选字段；Body 使用 Jakarta Validation；对外 <code>@Tag</code>、<code>@Operation</code>、<code>@Parameter</code> 齐全；禁止用 <code>IllegalArgumentException</code> 表达业务失败。</p><div class="vp-table"><table><thead><tr><th>能力</th><th>方法</th><th>路径</th><th>权限</th></tr></thead><tbody><tr><td>分页列表</td><td>GET</td><td><code>/system/user/list</code></td><td><code>system:user:list</code></td></tr><tr><td>详情</td><td>GET</td><td><code>/system/user/{userId}</code></td><td><code>system:user:list</code></td></tr><tr><td>新增</td><td>POST</td><td><code>/system/user/create</code></td><td><code>system:user:add</code></td></tr><tr><td>修改</td><td>POST</td><td><code>/system/user/update</code></td><td><code>system:user:edit</code></td></tr><tr><td>删除（批量）</td><td>POST</td><td><code>/system/user/remove</code></td><td><code>system:user:remove</code></td></tr><tr><td>改状态</td><td>POST</td><td><code>/system/user/changeStatus</code></td><td><code>system:user:edit</code></td></tr><tr><td>重置密码</td><td>POST</td><td><code>/system/user/resetPwd</code></td><td><code>system:user:resetPwd</code></td></tr><tr><td>分配角色-回显</td><td>GET</td><td><code>/system/user/authRole/{userId}</code></td><td><code>system:user:edit</code></td></tr><tr><td>分配角色-保存</td><td>POST</td><td><code>/system/user/authRole</code></td><td><code>system:user:edit</code></td></tr><tr><td>导入</td><td>POST</td><td><code>/system/user/importData</code></td><td><code>system:user:import</code></td></tr><tr><td>导入模板</td><td>GET</td><td><code>/system/user/importTemplate</code></td><td><code>system:user:import</code></td></tr><tr><td>导入失败明细下载</td><td>GET</td><td><code>/system/user/importError</code></td><td><code>system:user:import</code></td></tr><tr><td>导出</td><td>POST</td><td><code>/system/user/export</code></td><td><code>system:user:export</code></td></tr></tbody></table></div><p><strong>说明</strong></p><ul><li><strong>查询条件</strong>（列表 GET）：用户名模糊、手机号模糊、状态、创建时间区间起止、<code>deptId</code>（树选中，含子孙，见 §4.3）。</li><li><strong>重置密码</strong>：Body 含 <code>userId</code> 与<strong>新密码</strong>（明文由 HTTPS 保护；服务端按登录模块相同算法加密存储）；内置用户 <code>user_id=1</code> 允许重置密码（不在 §2「禁止停用/改用户名」限制内）。</li><li><strong>改状态</strong>：Body 含 <code>userId</code>、<code>status</code>；内置用户禁止改为停用态。</li><li><strong>导入</strong>：<code>multipart/form-data</code> 上传文件 + 参数 <code>updateSupport</code>（布尔）；<code>updateSupport=true</code> 时按 <code>user_name</code> 命中则更新（遵守内置用户字段限制），未命中则插入。<strong>响应 JSON</strong> 含：总条数、成功条数、失败条数、失败摘要列表（便于 toast）；若 <code>失败条数 &gt; 0</code>，响应内携带<strong>短时有效</strong>的 <code>errorKey</code>（或等价字段），前端再调 <strong><code>GET /system/user/importError?errorKey=</code></strong> 下载失败行 xlsx（服务端可内存/缓存限时存储，过期返回明确错误码）。</li><li><strong>导出</strong>：与列表筛选条件一致，文件格式 <strong>xlsx</strong>，使用 <code>quickboot-common</code> 既有 Excel 能力，与角色导出风格一致。</li></ul><h2 id="_6-后端设计" tabindex="-1">6. 后端设计 <a class="header-anchor vp-link" href="#_6-后端设计" aria-label="Permalink to &quot;6. 后端设计&quot;">​</a></h2><h3 id="_6-1-分层与包结构" tabindex="-1">6.1 分层与包结构 <a class="header-anchor vp-link" href="#_6-1-分层与包结构" aria-label="Permalink to &quot;6.1 分层与包结构&quot;">​</a></h3><ul><li>包路径：<code>io.github.genkidoudou.web.system.user</code>（与 <code>system.dept</code>、<code>system.role</code>、<code>system.config</code> 并列）。</li><li>分层：<code>controller</code> / <code>service</code> / <code>service.impl</code> / <code>mapper</code> / <code>domain</code> / <code>dto</code>（含 Bo、QueryBo、Vo、Excel 行对象、导入结果 VO）。</li></ul><h3 id="_6-2-内置用户-user-id-1" tabindex="-1">6.2 内置用户 <code>user_id = 1</code> <a class="header-anchor vp-link" href="#_6-2-内置用户-user-id-1" aria-label="Permalink to &quot;6.2 内置用户 `user_id = 1`&quot;">​</a></h3><ul><li><code>remove</code>：包含 <code>1</code> 则拒绝（可整单拒绝或跳过 <code>1</code> 并提示，实现选一种并在接口文档注明；<strong>推荐整单拒绝</strong>若列表含 <code>1</code>）。</li><li><code>update</code> / <code>changeStatus</code>：拦截改 <code>user_name</code>、将 <code>status</code> 改为停用。</li><li>其余字段与角色分配在通过校验前提下允许。</li></ul><h3 id="_6-3-业务校验-摘要" tabindex="-1">6.3 业务校验（摘要） <a class="header-anchor vp-link" href="#_6-3-业务校验-摘要" aria-label="Permalink to &quot;6.3 业务校验（摘要）&quot;">​</a></h3><ul><li><code>user_name</code> 全局唯一（与逻辑删除语义及 <code>del_flag</code> 规则一致）。</li><li>新增：<code>password</code> 必填；<strong><code>roleIds</code> 至少 1 个</strong>；<code>deptId</code> 必填（与原始需求一致；若业务允许未分配部门，须另开变更修订本文）。</li><li>编辑：<code>roleIds</code> 至少 1 个；密码非必填（不改则不带或空规则由实现约定）。</li><li>手机、邮箱格式校验；密码强度/长度与项目统一策略一致。</li><li><code>roleIds</code> 中每个 id 须在 <code>sys_role</code> 存在且未删除；<code>deptId</code> 须在 <code>sys_dept</code> 存在。</li></ul><h3 id="_6-4-依赖方向" tabindex="-1">6.4 依赖方向 <a class="header-anchor vp-link" href="#_6-4-依赖方向" aria-label="Permalink to &quot;6.4 依赖方向&quot;">​</a></h3><ul><li><code>SysUserService</code> 可依赖 <code>DeptService</code>（树筛选 id 集合、部门存在性）、对 <code>sys_role</code> 的只读查询。</li><li><strong>避免</strong> <code>UserService</code> ↔ <code>RoleService</code> 双向循环；角色写入用户关联时若需校验用户存在，保持 <strong>Role → UserMapper 只读</strong> 或已有模式。</li></ul><h3 id="_6-5-异常与审计" tabindex="-1">6.5 异常与审计 <a class="header-anchor vp-link" href="#_6-5-异常与审计" aria-label="Permalink to &quot;6.5 异常与审计&quot;">​</a></h3><ul><li>使用项目统一业务异常与 <code>ErrorCodes</code>；关键写操作审计字段由现有 MetaObjectHandler 填充。</li></ul><h2 id="_7-前端设计" tabindex="-1">7. 前端设计 <a class="header-anchor vp-link" href="#_7-前端设计" aria-label="Permalink to &quot;7. 前端设计&quot;">​</a></h2><ul><li><strong>路由</strong>：主列表 <code>/system/user</code>（与动态路由、后台菜单 <code>path</code>/<code>component</code> 一致）；分配角色子路由例如 <code>system/user/auth-role</code>（具体 <code>path</code> 与 <code>route_name</code> 与 <code>router</code> 表结构对齐），通过 <code>query</code> 或动态参数携带 <code>userId</code>。</li><li><strong>列表</strong>：查询区（用户名、手机、状态、创建时间范围、部门树 <code>treeselect</code>）；回车查询、重置；表格多选；状态 <code>el-switch</code> 变更前 <code>MessageBox</code> 二次确认；操作列：修改、删除、重置密码、分配角色等按权限显示。</li><li><strong>新增/编辑</strong>：弹窗组件；无岗位字段；角色多选；提交前前端校验至少一角色。</li><li><strong>分配角色页</strong>：展示可选角色列表（或分组）与已勾选；保存后返回用户列表并刷新。</li><li><strong>导入导出</strong>：导入选文件 + <code>updateSupport</code> 勾选；结果展示总数/成功/失败；失败时提供下载失败明细按钮（消费 <code>errorKey</code>）。导出按钮调用 <code>POST /system/user/export</code>。</li><li><strong>API</strong>：<code>quick-ui/src/api/system/user.js</code> <strong>全部</strong>改为本文 §5 路径；删除对 <code>/sys/user/*</code> 等与定稿不一致的调用。</li><li>样式与间距遵循 <strong><code>DESIGN.md</code></strong>。</li></ul><h2 id="_8-测试与验收" tabindex="-1">8. 测试与验收 <a class="header-anchor vp-link" href="#_8-测试与验收" aria-label="Permalink to &quot;8. 测试与验收&quot;">​</a></h2><ul><li>所有按钮与接口与 §2、§5 权限点一致；未授权按钮不可见；接口无权限返回与全局约定一致。</li><li>新增/编辑/删/改状态/重置密码/分配角色/导入导出后，列表数据与库表一致；<strong>新增/编辑无角色时前后端均拒绝</strong>。</li><li>内置用户：<code>user_id=1</code> 删除与禁用、改用户名被拒绝；其他允许字段修改成功。</li><li>导入：<code>updateSupport</code> 开/关行为与 §5 一致；失败条数与下载内容一致。</li><li>导出：xlsx 可打开，列与列表主要字段一致（无岗位列）。</li></ul><p>单元测试优先：内置用户规则、<code>user_name</code> 唯一、<code>roleIds</code> 非空、部门树筛选 id 集合；集成测试视 CI 选做。</p><h2 id="_9-文档与实现衔接" tabindex="-1">9. 文档与实现衔接 <a class="header-anchor vp-link" href="#_9-文档与实现衔接" aria-label="Permalink to &quot;9. 文档与实现衔接&quot;">​</a></h2><ul><li>实现前须阅读：<code>openspec/project.md</code>、<code>sdd/后端代码规范.md</code>、<code>sdd/前端代码规范.md</code>、<code>sdd/数据库设计规范.md</code>、根目录 <strong><code>DESIGN.md</code></strong>。</li><li>定稿评审通过后，使用 <strong><code>writing-plans</code></strong> 产出实现任务清单；<strong>不在本文档批准前</strong>启动业务编码。</li></ul><h2 id="_10-修订记录" tabindex="-1">10. 修订记录 <a class="header-anchor vp-link" href="#_10-修订记录" aria-label="Permalink to &quot;10. 修订记录&quot;">​</a></h2><div class="vp-table"><table><thead><tr><th>日期</th><th>说明</th></tr></thead><tbody><tr><td>2026-05-14</td><td>初版定稿（头脑风暴澄清：HTTP 契约、无岗位、子路由分配角色、导入键、内置用户规则、范围边界；确认新增/编辑须至少一角色）</td></tr></tbody></table></div>',46)])])}const m=o(s,[["render",c]]);export{h as __pageData,m as default};
